gameActivityImportAdditions.insert:

// CUSTOM:
import com.google.android.gms.auth.api.Auth;
import com.google.android.gms.auth.api.signin.GoogleSignIn;
import com.google.android.gms.auth.api.signin.GoogleSignInAccount;
import com.google.android.gms.auth.api.signin.GoogleSignInClient;
import com.google.android.gms.auth.api.signin.GoogleSignInOptions;
import com.google.android.gms.auth.api.signin.GoogleSignInResult;

gameActivityClassAdditions.insert:
    // CUSTOM: Google Auth Code
	  private static final int RC_SIGN_IN = 9001;
	  private GoogleSignInClient mGoogleSignInClient;

gameActivityOnCreateAdditions.insert:
newVirtualKeyboardInput.setScaleY(0);
// CUSTOM:
try
{
GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_GAMES_SIGN_IN)
.requestProfile()
.requestServerAuthCode("1087256936374-au0kmdkejdm1815j7m46gdi4cefkdp12.apps.googleusercontent.com")
.build();

mGoogleSignInClient = GoogleSignIn.getClient(this, gso);
}
catch (Exception e)
{
Log.debug("GoogleSignIn exception caught: " + e.toString());
}
Log.debug("mGoogleSignInClient is " + ((mGoogleSignInClient == null) ? "disabled" : "valid"));

gameActivityOnActivityResultAdditions.insert:
// CUSTOM: 
if(requestCode == RC_SIGN_IN)
{
	Log.debug("Google Client Connect: received RC_SIGN_IN");

	GoogleSignInResult result = Auth.GoogleSignInApi.getSignInResultFromIntent(data);
	if (result.isSuccess())
	{
		Log.debug("Google Client Connect: Got sign in result");
		try
		{
			Log.debug("Google Client Connect: Getting account");
			GoogleSignInAccount account = result.getSignInAccount();

			if(account != null)
			{
				Log.debug("Google Client Connect: Got account");
				String mServerAuthCode = account.getServerAuthCode();
				if(!mServerAuthCode.equals(""))
				{
					Log.debug("Google Client Connect succeeded");
					nativeGoogleClientConnectCompleted(true, mServerAuthCode);
				}
				else
				{
					Log.debug("Google Client Connect succeeded but no access token returned");
					nativeGoogleClientConnectCompleted(true, "NOT_ACQUIRED");
				}
			}

		}
		catch (Exception e)
		{
			Log.debug("Google Client Connect failed to get auth token: " + e.getMessage());

			nativeGoogleClientConnectCompleted(false, "NOT_ACQUIRED");
		}
	}
	else
	{
		Log.debug("Google Client Connect result was a fail");
		nativeGoogleClientConnectCompleted(false, "NOT_ACQUIRED");
	}
}
